INSERT INTO notification_templates (event_key, channel, name, subject, body) VALUES
('user.welcome', 'email', 'Boas-vindas ao cliente', 'Bem-vindo à {{site_name}}, {{customer_name}}!', '<p>Olá {{customer_name}},</p><p>A sua conta na {{site_name}} foi criada com sucesso. Já pode acompanhar encomendas, guardar favoritos e receber novidades.</p><p><a href="{{site_url}}/shop">Explorar a loja</a></p><p>Equipa {{site_name}}</p>'),
('user.welcome', 'in_app', 'Boas-vindas ao cliente', 'Bem-vindo à GameAO', 'A sua conta foi criada com sucesso. Explore o catálogo e acompanhe as suas encomendas na área de cliente.'),
('user.password_reset', 'email', 'Recuperação de palavra-passe', 'Recuperação de palavra-passe · {{site_name}}', '<p>Olá {{customer_name}},</p><p>Recebemos um pedido para redefinir a palavra-passe da sua conta {{site_name}}. O link é válido durante {{reset_minutes}} minutos.</p><p><a href="{{reset_link}}">Redefinir palavra-passe</a></p><p>Se não fez este pedido, ignore este email. A sua palavra-passe mantém-se inalterada.</p><p>Equipa {{site_name}}</p>'),
('order.created', 'email', 'Encomenda recebida', 'Encomenda {{order_number}} recebida · {{site_name}}', '<p>Olá {{customer_name}},</p><p>Recebemos a sua encomenda <strong>{{order_number}}</strong> no valor de <strong>{{order_total}}</strong>.</p>{{order_items}}<p>Método de pagamento: {{payment_method}}</p><p>{{payment_instructions}}</p><p><a href="{{order_link}}">Acompanhar encomenda</a></p><p>Equipa {{site_name}}</p>'),
('order.created', 'whatsapp', 'Encomenda recebida', 'Encomenda recebida', 'Olá {{customer_name}}! Recebemos a sua encomenda {{order_number}} no valor de {{order_total}}. Acompanhe em {{order_link}}'),
('order.created', 'in_app', 'Encomenda recebida', 'Encomenda {{order_number}} recebida', 'A sua encomenda de {{order_total}} foi registada. Consulte o estado e as instruções de pagamento.'),
('order.payment_proof_submitted', 'email', 'Comprovativo recebido', 'Comprovativo da encomenda {{order_number}} recebido', '<p>Olá {{customer_name}},</p><p>Recebemos o comprovativo de pagamento da encomenda <strong>{{order_number}}</strong>. A equipa vai rever o documento e confirmar o pagamento.</p><p><a href="{{order_link}}">Ver encomenda</a></p>'),
('order.payment_proof_submitted', 'in_app', 'Comprovativo recebido', 'Comprovativo recebido', 'O comprovativo da encomenda {{order_number}} foi recebido e está em análise.'),
('order.payment_confirmed', 'email', 'Pagamento confirmado', 'Pagamento confirmado · Encomenda {{order_number}}', '<p>Olá {{customer_name}},</p><p>O pagamento da encomenda <strong>{{order_number}}</strong> foi confirmado. O pedido segue agora para processamento.</p><p><a href="{{order_link}}">Acompanhar encomenda</a></p><p>Equipa {{site_name}}</p>'),
('order.payment_confirmed', 'whatsapp', 'Pagamento confirmado', 'Pagamento confirmado', 'Olá {{customer_name}}! O pagamento da encomenda {{order_number}} foi confirmado. Vamos processar o seu pedido. Detalhes: {{order_link}}'),
('order.payment_confirmed', 'in_app', 'Pagamento confirmado', 'Pagamento confirmado', 'O pagamento da encomenda {{order_number}} foi confirmado. O pedido está em processamento.'),
('order.processing', 'email', 'Encomenda em processamento', 'A sua encomenda {{order_number}} está em processamento', '<p>Olá {{customer_name}},</p><p>A encomenda <strong>{{order_number}}</strong> está a ser preparada pela nossa equipa.</p><p><a href="{{order_link}}">Acompanhar encomenda</a></p>'),
('order.processing', 'whatsapp', 'Encomenda em processamento', 'Encomenda em processamento', 'Olá {{customer_name}}! A sua encomenda {{order_number}} está em processamento. Acompanhe em {{order_link}}'),
('order.processing', 'in_app', 'Encomenda em processamento', 'Encomenda em processamento', 'A encomenda {{order_number}} está a ser preparada.'),
('order.ready_for_delivery', 'email', 'Encomenda pronta', 'A sua encomenda {{order_number}} está pronta para entrega', '<p>Olá {{customer_name}},</p><p>A encomenda <strong>{{order_number}}</strong> está pronta para entrega. A nossa equipa entrará em contacto para combinar os detalhes.</p><p><a href="{{order_link}}">Ver encomenda</a></p>'),
('order.ready_for_delivery', 'whatsapp', 'Encomenda pronta', 'Encomenda pronta', 'Olá {{customer_name}}! A sua encomenda {{order_number}} está pronta para entrega. Vamos contactá-lo para combinar. Detalhes: {{order_link}}'),
('order.ready_for_delivery', 'in_app', 'Encomenda pronta', 'Encomenda pronta para entrega', 'A encomenda {{order_number}} está pronta. A equipa entrará em contacto.'),
('order.completed', 'email', 'Encomenda concluída', 'Encomenda {{order_number}} concluída · Obrigado!', '<p>Olá {{customer_name}},</p><p>A encomenda <strong>{{order_number}}</strong> foi concluída. Obrigado por comprar na {{site_name}}.</p><p>Pode descarregar a fatura em <a href="{{order_link}}">acompanhar encomenda</a>.</p><p>Equipa {{site_name}}</p>'),
('order.completed', 'whatsapp', 'Encomenda concluída', 'Encomenda concluída', 'Olá {{customer_name}}! A encomenda {{order_number}} foi concluída. Obrigado pela preferência. Fatura: {{order_link}}'),
('order.completed', 'in_app', 'Encomenda concluída', 'Encomenda concluída', 'A encomenda {{order_number}} foi concluída. Obrigado pela sua compra!'),
('order.cancelled', 'email', 'Encomenda cancelada', 'Encomenda {{order_number}} cancelada', '<p>Olá {{customer_name}},</p><p>A encomenda <strong>{{order_number}}</strong> foi cancelada. Se não reconhece este cancelamento, contacte-nos.</p><p><a href="{{site_url}}/contact-us">Contactar a GameAO</a></p>'),
('order.cancelled', 'whatsapp', 'Encomenda cancelada', 'Encomenda cancelada', 'Olá {{customer_name}}. A encomenda {{order_number}} foi cancelada. Em caso de dúvida, fale com a GameAO.'),
('order.cancelled', 'in_app', 'Encomenda cancelada', 'Encomenda cancelada', 'A encomenda {{order_number}} foi cancelada. Contacte-nos se precisar de ajuda.'),
('order.refunded', 'email', 'Encomenda reembolsada', 'Reembolso da encomenda {{order_number}}', '<p>Olá {{customer_name}},</p><p>O reembolso da encomenda <strong>{{order_number}}</strong> foi registado. O valor de {{order_total}} será devolvido pelo mesmo meio de pagamento.</p>'),
('order.refunded', 'whatsapp', 'Encomenda reembolsada', 'Reembolso registado', 'Olá {{customer_name}}. O reembolso da encomenda {{order_number}} ({{order_total}}) foi registado.'),
('order.refunded', 'in_app', 'Encomenda reembolsada', 'Reembolso registado', 'O reembolso da encomenda {{order_number}} foi registado.'),
('order.payment_rejected', 'email', 'Comprovativo rejeitado', 'Comprovativo da encomenda {{order_number}} rejeitado', '<p>Olá {{customer_name}},</p><p>O comprovativo enviado para a encomenda <strong>{{order_number}}</strong> não pôde ser aceite. {{admin_note}}</p><p>Envie um novo comprovativo em <a href="{{order_link}}">acompanhar encomenda</a>.</p>'),
('order.payment_rejected', 'whatsapp', 'Comprovativo rejeitado', 'Comprovativo rejeitado', 'Olá {{customer_name}}. O comprovativo da encomenda {{order_number}} foi rejeitado. {{admin_note}} Envie um novo em {{order_link}}'),
('order.payment_rejected', 'in_app', 'Comprovativo rejeitado', 'Comprovativo rejeitado', 'O comprovativo da encomenda {{order_number}} não foi aceite. Envie um novo documento.'),
('order.payment_proof_requested', 'email', 'Novo comprovativo pedido', 'Precisamos de um novo comprovativo · {{order_number}}', '<p>Olá {{customer_name}},</p><p>Para continuar com a encomenda <strong>{{order_number}}</strong>, precisamos de um novo comprovativo de pagamento. {{admin_note}}</p><p><a href="{{order_link}}">Enviar comprovativo</a></p>'),
('order.payment_proof_requested', 'whatsapp', 'Novo comprovativo pedido', 'Novo comprovativo', 'Olá {{customer_name}}. Precisamos de um novo comprovativo para a encomenda {{order_number}}. {{admin_note}} Envie em {{order_link}}'),
('order.payment_proof_requested', 'in_app', 'Novo comprovativo pedido', 'Novo comprovativo necessário', 'Precisamos de um novo comprovativo para a encomenda {{order_number}}.'),
('admin.new_order', 'in_app', 'Nova encomenda (administração)', 'Nova encomenda {{order_number}}', '{{customer_name}} fez uma encomenda de {{order_total}} com o método {{payment_method}}.'),
('admin.new_order', 'email', 'Nova encomenda (email)', 'Nova encomenda {{order_number}} · {{site_name}}', '<p>Nova encomenda <strong>{{order_number}}</strong> de {{customer_name}} ({{customer_email}}).</p><p>Total: {{order_total}} · Pagamento: {{payment_method}}</p><p><a href="{{admin_link}}">Abrir no painel</a></p>'),
('admin.new_customer', 'in_app', 'Novo cliente', 'Novo cliente registado', '{{customer_name}} ({{customer_email}}) criou uma conta na loja.'),
('admin.new_customer', 'email', 'Novo cliente (email)', 'Novo cliente · {{site_name}}', '<p>O cliente <strong>{{customer_name}}</strong> ({{customer_email}}) criou uma conta.</p>'),
('admin.payment_proof', 'in_app', 'Novo comprovativo', 'Novo comprovativo · {{order_number}}', '{{customer_name}} enviou um comprovativo de pagamento de {{order_total}}. Reveja o documento antes de aprovar.'),
('admin.payment_proof', 'email', 'Novo comprovativo (email)', 'Novo comprovativo · {{order_number}}', '<p>{{customer_name}} enviou um comprovativo para a encomenda <strong>{{order_number}}</strong>.</p><p><a href="{{admin_link}}">Rever comprovativo</a></p>'),
('admin.contact_message', 'in_app', 'Nova mensagem de contacto', 'Nova mensagem de {{contact_name}}', '{{contact_message}}'),
('admin.contact_message', 'email', 'Nova mensagem de contacto (email)', 'Nova mensagem de contacto · {{site_name}}', '<p><strong>{{contact_name}}</strong> ({{contact_email}}) enviou uma mensagem:</p><p>{{contact_message}}</p>'),
('admin.low_stock', 'in_app', 'Stock baixo', 'Stock baixo · {{product_name}}', 'Restam {{stock_quantity}} unidades de {{product_name}}. Reponha o stock para evitar vendas em falta.'),
('admin.low_stock', 'email', 'Stock baixo (email)', 'Stock baixo · {{product_name}}', '<p>O produto <strong>{{product_name}}</strong> tem apenas {{stock_quantity}} unidades.</p>'),
('blog.comment_pending', 'in_app', 'Comentário pendente', 'Novo comentário em {{post_title}}', '{{customer_name}} escreveu: {{comment_excerpt}}'),
('blog.comment_approved', 'email', 'Comentário aprovado', 'O seu comentário foi publicado · {{site_name}}', '<p>Olá {{customer_name}},</p><p>O seu comentário em <strong>{{post_title}}</strong> foi aprovado e já está visível.</p><p><a href="{{comment_link}}">Ver artigo</a></p>'),
('blog.comment_approved', 'in_app', 'Comentário aprovado', 'Comentário publicado', 'O seu comentário em {{post_title}} foi aprovado.'),
('blog.comment_rejected', 'in_app', 'Comentário rejeitado', 'Comentário não publicado', 'O seu comentário em {{post_title}} não foi publicado. Contacte-nos para mais informação.'),
('affiliate.joined', 'email', 'Programa de afiliados', 'O seu código de afiliado GameAO: {{affiliate_code}}', '<p>Olá {{customer_name}},</p><p>Bem-vindo ao programa de afiliados {{site_name}}. O seu código é <strong>{{affiliate_code}}</strong> e a comissão é de {{commission_rate}}% por venda confirmada.</p><p><a href="{{site_url}}/afiliados">Ver o meu painel de afiliado</a></p>'),
('affiliate.joined', 'in_app', 'Programa de afiliados', 'Bem-vindo ao programa de afiliados', 'O seu código {{affiliate_code}} está ativo. Partilhe-o e ganhe {{commission_rate}}% por venda confirmada.'),
('affiliate.commission', 'email', 'Comissão de afiliado', 'Ganhou uma comissão de {{commission}}', '<p>Olá {{customer_name}},</p><p>Ganhou <strong>{{commission}}</strong> de comissão com a encomenda {{order_number}}.</p><p><a href="{{site_url}}/afiliados">Ver saldo</a></p>'),
('affiliate.commission', 'in_app', 'Comissão de afiliado', 'Comissão recebida', 'Ganhou {{commission}} com a encomenda {{order_number}}.'),
('affiliate.payout', 'email', 'Pagamento de comissões', 'Comissões pagas · {{payout_amount}}', '<p>Olá {{customer_name}},</p><p>Processámos o pagamento de <strong>{{payout_amount}}</strong> em comissões.</p>'),
('affiliate.payout', 'in_app', 'Pagamento de comissões', 'Comissões pagas', 'Recebeu {{payout_amount}} em comissões.'),
('admin.affiliate_request', 'in_app', 'Pedido de afiliado', 'Novo afiliado: {{customer_name}}', '{{customer_name}} ({{customer_email}}) aderiu ao programa com o código {{affiliate_code}}.'),
('admin.affiliate_withdraw', 'in_app', 'Pedido de pagamento de afiliado', 'Pedido de pagamento · {{customer_name}}', 'O afiliado {{customer_name}} pediu o pagamento de {{payout_amount}}.')
